from typing import Optional
from .base import AHBaseReportInfo
from .protocols import AHReportType, AHHTTPMethod, AHReportError


class AHModelAccessibilityReport:
    report_type = AHReportType.MODEL_ACCESSIBILITY
    http_method = AHHTTPMethod.GET

    def __init__(self, base_info: AHBaseReportInfo, username: str, model: str,
                 source_type: str = '1', git_url: Optional[str] = None):
        self.base_info = base_info
        self.username = username
        self.model = model
        self.source_type = source_type
        self.git_url = git_url
        self.base_url = self.report_type.base_url()
        self.endpoint = self.report_type.endpoint()

    def parameters(self) -> dict:
        return {
            'username': self.username,
            'model': self.model,
            'sourcetype': self.source_type,
        }

    def validate(self):
        if not self.username or not self.username.strip():
            raise AHReportError.validation_failed('Username cannot be empty')
        if not self.model or not self.model.strip():
            raise AHReportError.validation_failed('Model cannot be empty')


